lockMutationStatements:
perform pg_advisory_xact_lock(hashtextextended(
      ''||v_account_id::text||''||btrim(p_idempotency_key),0
    ))

perform pg_advisory_xact_lock(hashtextextended(
      ''||p_workflow_id::text,0
    ))

if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended('', 0)
  ) then
    return jsonb_build_object(
      '',true,
      '',p_workflow_id,
      '',p_expected_generation,
      '','',
      '',true,
      '',true,
      '',''
    )

if not pg_catalog.pg_try_advisory_xact_lock(
    pg_catalog.hashtextextended(
      '' || p_workflow_id::text || '' || p_expected_generation::text,
      0
    )
  ) then
    return jsonb_build_object(
      '',true,
      '',p_workflow_id,
      '',p_expected_generation,
      '','',
      '',true,
      '',true,
      '',''
    )

perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    ''||v_client::text,0
  ))

insert into public.invoices(
    type,client_id,status,status_date_utc,subtotal_ex_vat,vat_amount,total_inc_vat,
    notes,header_snapshot_json,do_not_send,document_revision,document_state,issue_state
  ) values (
    '',v_manifest.client_id,'',pg_catalog.transaction_timestamp(),0,0,0,
    case when v_manifest.backing_report_number is null then null
      else ''||v_manifest.backing_report_number end,
    v_header,false,1,'',''
  ) returning id into v_invoice_id
